const MAX_REGISTRY_RESPONSE_BYTES: usize = 4 * 1024 * 1024;
const MCP_REGISTRY_CACHE_SCHEMA_VERSION: u32 = 1;
const MCP_REGISTRY_CACHE_FRESH_MILLIS: u64 = 15 * 60 * 1000;
const MCP_REGISTRY_CACHE_MAX_ENTRIES: usize = 64;
