fn artloom_compat_fetch_mcp_registry(
    path: &str,
    endpoint: &str,
    cache_path: &Path,
) -> Result<(u16, String)> {
    let (status, body) = fetch_mcp_registry(path, endpoint, cache_path)?;
    if status != 200 {
        return Ok((status, body));
    }
    let mut value =
        serde_json::from_str::<Value>(&body).unwrap_or_else(|_| json!({ "data": body }));
    if let Some(object) = value.as_object_mut() {
        object.insert(
            "compatCommand".to_owned(),
            Value::String("fetch_mcp_registry".to_owned()),
        );
    } else {
        value = json!({
            "compatCommand": "fetch_mcp_registry",
            "data": value,
        });
    }
    Ok((200, serde_json::to_string(&value)?))
}

fn fetch_mcp_registry(path: &str, endpoint: &str, cache_path: &Path) -> Result<(u16, String)> {
    let _fetch_guard = MCP_REGISTRY_FETCH_LOCK
        .get_or_init(|| Mutex::new(()))
        .lock()
        .map_err(|_| anyhow::anyhow!("lock MCP Registry fetch state"))?;
    let search = query_value(path, "search");
    let cursor = query_value(path, "cursor");
    let limit = query_value(path, "limit").and_then(|value| value.parse::<u32>().ok());
    let updated_since =
        query_value(path, "updated_since").or_else(|| query_value(path, "updatedSince"));
    let version = query_value(path, "version");
    let include_deleted = query_value(path, "include_deleted")
        .or_else(|| query_value(path, "includeDeleted"))
        .is_some_and(|value| matches!(value.as_str(), "1" | "true"));
    let refresh =
        query_value(path, "refresh").is_some_and(|value| matches!(value.as_str(), "1" | "true"));
    let url = build_mcp_registry_url(
        endpoint,
        search.as_deref(),
        limit,
        cursor.as_deref(),
        updated_since.as_deref(),
        version.as_deref(),
        include_deleted,
    );
    let now = unix_time_millis();
    let cached = load_mcp_registry_cache(cache_path).entries.remove(&url);
    if !refresh {
        if let Some(entry) = cached.as_ref().filter(|entry| {
            now.saturating_sub(entry.fetched_at_ms) <= MCP_REGISTRY_CACHE_FRESH_MILLIS
        }) {
            let response = annotate_mcp_registry_response(
                entry.response.clone(),
                "cache",
                false,
                entry.fetched_at_ms,
            );
            return Ok((200, serde_json::to_string(&response)?));
        }
    }

    let policy = user_configured_outbound_policy();
    let client = secure_client(
        "Loom/0.1 MCP Registry Client",
        Duration::from_secs(20),
        policy.clone(),
    )
    .map_err(|error| anyhow::anyhow!("build MCP Registry client: {error}"))?;
    let mut bytes = None;
    let mut fetch_error = None;
    for attempt in 0..MCP_REGISTRY_FETCH_ATTEMPTS {
        match get_bounded(&client, &url, &policy, MAX_REGISTRY_RESPONSE_BYTES) {
            Ok(response_bytes) => {
                bytes = Some(response_bytes);
                break;
            }
            Err(error) => {
                fetch_error = Some(error.to_string());
                if attempt + 1 < MCP_REGISTRY_FETCH_ATTEMPTS {
                    std::thread::sleep(MCP_REGISTRY_RETRY_DELAY);
                }
            }
        }
    }
    let bytes = match bytes {
        Some(bytes) => bytes,
        None => {
            let error = fetch_error.unwrap_or_else(|| "unknown MCP Registry error".to_owned());
            if let Some(entry) = cached {
                let response = annotate_mcp_registry_response(
                    entry.response,
                    "cache",
                    true,
                    entry.fetched_at_ms,
                );
                return Ok((200, serde_json::to_string(&response)?));
            }
            return structured_error(
                502,
                json!({
                    "code": "mcp_registry_unavailable",
                    "message": format!("failed to fetch MCP Registry: {error}"),
                    "url": url,
                }),
            );
        }
    };
    let value = match serde_json::from_slice::<Value>(&bytes) {
        Ok(value) => value,
        Err(error) => {
            if let Some(entry) = cached {
                let response = annotate_mcp_registry_response(
                    entry.response,
                    "cache",
                    true,
                    entry.fetched_at_ms,
                );
                return Ok((200, serde_json::to_string(&response)?));
            }
            return structured_error(
                502,
                json!({
                    "code": "mcp_registry_invalid_json",
                    "message": format!("MCP Registry returned invalid JSON: {error}"),
                    "url": url,
                }),
            );
        }
    };

    cache_mcp_registry_response(cache_path, &url, &value, now);
    let response = annotate_mcp_registry_response(value, "network", false, now);
    Ok((200, serde_json::to_string(&response)?))
}

fn test_mcp_connection(body: &str) -> Result<(u16, String)> {
    let config: McpServerConfig = match serde_json::from_str(body) {
        Ok(config) => config,
        Err(error) => {
            return structured_error(
                400,
                json!({
                    "compatCommand": "test_mcp_connection",
                    "code": "invalid_mcp_server",
                    "message": format!("invalid MCP server config: {error}"),
                }),
            );
        }
    };
    let config = normalize_mcp_server_config(config);

    let mut client = match McpClient::connect(&config) {
        Ok(client) => client,
        Err(error) => {
            return Ok((
                200,
                serde_json::to_string(&json!({
                    "compatCommand": "test_mcp_connection",
                    "success": false,
                    "tools": [],
                    "error": error.to_string(),
                }))?,
            ));
        }
    };
    let server_info = match client.initialize() {
        Ok(server_info) => server_info,
        Err(error) => {
            return Ok((
                200,
                serde_json::to_string(&json!({
                    "compatCommand": "test_mcp_connection",
                    "success": false,
                    "tools": [],
                    "error": error.to_string(),
                }))?,
            ));
        }
    };
    let tools_result = match client.list_tools() {
        Ok(tools) => tools,
        Err(error) => {
            return Ok((
                200,
                serde_json::to_string(&json!({
                    "compatCommand": "test_mcp_connection",
                    "success": false,
                    "tools": [],
                    "server_info": server_info,
                    "serverInfo": server_info,
                    "error": error.to_string(),
                }))?,
            ));
        }
    };
    let tools = tools_result
        .get("tools")
        .cloned()
        .unwrap_or_else(|| json!([]));

    Ok((
        200,
        serde_json::to_string(&json!({
            "compatCommand": "test_mcp_connection",
            "success": true,
            "tools": tools,
            "server_info": server_info,
            "serverInfo": server_info,
        }))?,
    ))
}

fn artloom_compat_call_mcp_tool(body: &str) -> Result<(u16, String)> {
    let request: ArtLoomCompatCallMcpToolRequest = match serde_json::from_str(body) {
        Ok(request) => request,
        Err(error) => return invalid_request(error.to_string()),
    };
    let tool_name = request.tool_name.trim();
    if tool_name.is_empty() {
        return invalid_request("toolName is required");
    }

    let config = McpServerConfig {
        id: "artloom-compat-direct".to_owned(),
        name: "ArtLoom Compat Direct MCP".to_owned(),
        description: "One-shot ArtLoom call_mcp_tool compatibility server".to_owned(),
        command: request.command.trim().to_owned(),
        args: request.args,
        env: request.env,
        transport: request.transport,
        url: request.url.trim().to_owned(),
        headers: request.headers,
        enabled: true,
    };
    if let Err(error) = config.validate() {
        return invalid_request(error.to_string());
    }
    let mut client = match McpClient::connect(&config) {
        Ok(client) => client,
        Err(error) => {
            return structured_error(
                502,
                json!({
                    "compatCommand": "call_mcp_tool",
                    "code": "mcp_spawn_failed",
                    "message": error.to_string(),
                }),
            );
        }
    };
    if let Err(error) = client.initialize() {
        return structured_error(
            502,
            json!({
                "compatCommand": "call_mcp_tool",
                "code": "mcp_initialize_failed",
                "message": error.to_string(),
            }),
        );
    }
    let result = match client.call_tool(tool_name, request.tool_args) {
        Ok(result) => result,
        Err(error) => {
            return structured_error(
                502,
                json!({
                    "compatCommand": "call_mcp_tool",
                    "code": "mcp_tool_call_failed",
                    "message": error.to_string(),
                }),
            );
        }
    };

    Ok((
        200,
        serde_json::to_string(&json!({
            "compatCommand": "call_mcp_tool",
            "status": "succeeded",
            "jsonrpc": "2.0",
            "id": 3,
            "result": result,
        }))?,
    ))
}

fn check_mcp_package_installed(body: &str) -> Result<(u16, String)> {
    let request: McpPackageCheckRequest = match serde_json::from_str(body) {
        Ok(request) => request,
        Err(error) => return invalid_request(error.to_string()),
    };
    let module_name = request.module_name.trim();
    if !is_safe_python_module_name(module_name) {
        return invalid_request("moduleName must be a dotted Python module identifier");
    }

    let python = resolve_mcp_package_python();
    let output = Command::new(&python)
        .args(["-c", &format!("import {module_name}")])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output();

    let value = match output {
        Ok(output) => json!({
            "compatCommand": "check_mcp_package_installed",
            "installed": output.status.success(),
            "module": module_name,
            "python": python.to_string_lossy(),
            "stdout": String::from_utf8_lossy(&output.stdout).to_string(),
            "stderr": String::from_utf8_lossy(&output.stderr).to_string(),
        }),
        Err(error) => json!({
            "compatCommand": "check_mcp_package_installed",
            "installed": false,
            "module": module_name,
            "python": python.to_string_lossy(),
            "error": error.to_string(),
        }),
    };

    Ok((200, serde_json::to_string(&value)?))
}

fn build_mcp_package_install_plan(body: &str) -> Result<(u16, String)> {
    let request: McpPackageInstallPlanRequest = match serde_json::from_str(body) {
        Ok(request) => request,
        Err(error) => return invalid_request(error.to_string()),
    };
    let package_name = request.package_name.trim();
    if !is_safe_python_package_name(package_name) {
        return invalid_request("packageName must be a safe pip package specifier");
    }
    let python = resolve_mcp_package_python();
    let command = vec![
        python.to_string_lossy().to_string(),
        "-m".to_owned(),
        "pip".to_owned(),
        "install".to_owned(),
        "--upgrade".to_owned(),
        package_name.to_owned(),
    ];

    Ok((
        200,
        serde_json::to_string(&json!({
            "compatCommand": "install_mcp_package",
            "package": package_name,
            "sideEffect": false,
            "mode": "safe-preview",
            "command": command,
            "message": "Install plan prepared. Loom does not run arbitrary package installation from this compatibility preview.",
        }))?,
    ))
}

fn resolve_mcp_package_python() -> PathBuf {
    if let Some(path) = std::env::var_os("LOOM_PYTHON").map(PathBuf::from) {
        return path;
    }
    if let Ok(current_exe) = std::env::current_exe() {
        if let Some(base) = current_exe.parent() {
            let packaged = base.join("bin").join("python-embed").join("python.exe");
            if packaged.exists() {
                return packaged;
            }
        }
    }
    PathBuf::from(if cfg!(windows) {
        "python.exe"
    } else {
        "python3"
    })
}

fn is_safe_python_module_name(value: &str) -> bool {
    !value.is_empty()
        && value.split('.').all(|segment| {
            let mut chars = segment.chars();
            let Some(first) = chars.next() else {
                return false;
            };
            (first == '_' || first.is_ascii_alphabetic())
                && chars.all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
        })
}

fn is_safe_python_package_name(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 160
        && value
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '-' | '.' | '[' | ']' | '='))
}

fn list_tools(tool_registry: &ToolRegistry) -> Result<(u16, String)> {
    let tools = match tool_registry.list_tools() {
        Ok(tools) => tools,
        Err(error) => return tool_registry_error_response(error),
    };
    Ok((200, serde_json::to_string(&json!({ "tools": tools }))?))
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct InstallArtRequest {
    /// The art package zip, base64-encoded (data URL or raw base64).
    zip_base64: String,
    #[serde(default)]
    bundled_catalog: bool,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CreateAuthoredArtRequest {
    tool: ToolDefinition,
    #[serde(default)]
    runtime: Option<ArtRuntimeManifest>,
    #[serde(default)]
    files: Vec<CreateAuthoredArtFile>,
    #[serde(default)]
    source_directory: Option<String>,
    #[serde(default)]
    source_directory_target: Option<String>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct CreateAuthoredArtFile {
    path: String,
    content: String,
}

fn collect_authored_art_files(
    request: &CreateAuthoredArtRequest,
) -> std::result::Result<Vec<(String, Vec<u8>)>, String> {
    const MAX_AUTHORED_FILES: usize = 4096;
    const MAX_AUTHORED_BYTES: u64 = 32 * 1024 * 1024;

    let mut files = request
        .files
        .iter()
        .map(|file| (file.path.clone(), file.content.as_bytes().to_vec()))
        .collect::<Vec<_>>();
    let mut total_bytes = files
        .iter()
        .map(|(_, content)| content.len() as u64)
        .sum::<u64>();
    let Some(source_directory) = request
        .source_directory
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        if files.len() > MAX_AUTHORED_FILES || total_bytes > MAX_AUTHORED_BYTES {
            return Err("authored Art resources exceed the package limits".to_owned());
        }
        return Ok(files);
    };

    let source_root = fs::canonicalize(source_directory)
        .map_err(|error| format!("cannot resolve authored Art source directory: {error}"))?;
    if !source_root.is_dir() {
        return Err("authored Art sourceDirectory must be a directory".to_owned());
    }
    let target = request
        .source_directory_target
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("runtime/plugin")
        .replace('\\', "/");
    if target.starts_with('/')
        || target.contains(':')
        || target
            .split('/')
            .any(|segment| segment.is_empty() || segment == "..")
    {
        return Err("authored Art sourceDirectoryTarget must be a safe relative path".to_owned());
    }

    let mut pending = vec![source_root.clone()];
    while let Some(directory) = pending.pop() {
        for entry in fs::read_dir(&directory)
            .map_err(|error| format!("cannot read authored Art source directory: {error}"))?
        {
            let entry =
                entry.map_err(|error| format!("cannot read authored Art source: {error}"))?;
            let file_type = entry
                .file_type()
                .map_err(|error| format!("cannot inspect authored Art source: {error}"))?;
            if file_type.is_symlink() {
                return Err(format!(
                    "authored Art source cannot contain symbolic links: {}",
                    entry.path().display()
                ));
            }
            if file_type.is_dir() {
                pending.push(entry.path());
                continue;
            }
            if !file_type.is_file() {
                continue;
            }
            let relative = entry
                .path()
                .strip_prefix(&source_root)
                .map_err(|error| format!("cannot relativize authored Art source: {error}"))?
                .to_string_lossy()
                .replace('\\', "/");
            let content = fs::read(entry.path())
                .map_err(|error| format!("cannot read authored Art source file: {error}"))?;
            total_bytes = total_bytes.saturating_add(content.len() as u64);
            files.push((format!("{target}/{relative}"), content));
            if files.len() > MAX_AUTHORED_FILES || total_bytes > MAX_AUTHORED_BYTES {
                return Err("authored Art resources exceed the package limits".to_owned());
            }
        }
    }
    Ok(files)
}

fn create_authored_art(
    body: &str,
    tool_registry: &ToolRegistry,
    framework_registry: &FrameworkRegistry,
    control_plane_root: &Path,
    hook_bridge: &SharedHookBridgeRuntime,
) -> Result<(u16, String)> {
    let request: CreateAuthoredArtRequest = match serde_json::from_str(body) {
        Ok(request) => request,
        Err(error) => return invalid_request(error.to_string()),
    };
    if matches!(&request.tool.execution, ToolExecution::FrameworkArt { .. })
        && request.runtime.is_none()
    {
        return invalid_request("framework_art authoring requires an art runtime manifest");
    }
    let files = match collect_authored_art_files(&request) {
        Ok(files) => files,
        Err(error) => return invalid_request(error),
    };
    let qualified_id = request.tool.qualified_id();
    let zip = match loom_tool_registry::install::build_authored_art_package_zip(
        &request.tool,
        request.runtime.as_ref(),
        &files,
    ) {
        Ok(zip) => zip,
        Err(error) => return invalid_request(error.to_string()),
    };
    match loom_tool_registry::install::install_authored_art_from_zip(
        &zip,
        control_plane_root,
        framework_registry,
        tool_registry,
    ) {
        Ok(report) => {
            let _ = broadcast_artloom_compat_arts_updated(hook_bridge);
            let tool = tool_registry
                .get_tool(&qualified_id)
                .ok()
                .flatten()
                .unwrap_or(request.tool);
            Ok((
                200,
                serde_json::to_string(&json!({ "report": report, "tool": tool }))?,
            ))
        }
        Err(loom_tool_registry::install::ArtInstallError::FrameworkNotReady {
            art_id,
            framework,
            reason,
        }) => structured_error(
            409,
            json!({
                "code": "framework_not_ready",
                "message": format!("art `{art_id}` requires framework `{framework}` ({reason})"),
                "framework": framework,
            }),
        ),
        Err(error) => structured_error(
            400,
            json!({ "code": "art_create_failed", "message": error.to_string() }),
        ),
    }
}

// Install an art package (zip) into the registry: extracts to <root>/arts/<id>/,
// checks the framework is ready, and registers the ToolDefinition.
fn install_art(
    body: &str,
    tool_registry: &ToolRegistry,
    framework_registry: &FrameworkRegistry,
    control_plane_root: &Path,
    hook_bridge: &SharedHookBridgeRuntime,
    bundled_art_sha256_allowlist: &BTreeSet<String>,
) -> Result<(u16, String)> {
    let request = match serde_json::from_str::<InstallArtRequest>(body) {
        Ok(request) => request,
        Err(error) => return invalid_request(error.to_string()),
    };
    let zip_bytes = match loom_image_io::decode_data_url_bytes(&request.zip_base64) {
        Ok(bytes) => bytes,
        Err(error) => return invalid_request(format!("decode art package: {error}")),
    };
    let result = if request.bundled_catalog {
        let package_sha256 = sha256_bytes(&zip_bytes);
        if !bundled_art_sha256_allowlist.contains(&package_sha256) {
            return structured_error(
                403,
                json!({
                    "code": "bundled_art_not_allowlisted",
                    "message": "bundled Art package digest is not authorized by the daemon launch catalog",
                }),
            );
        }
        loom_tool_registry::install::install_bundled_art_from_zip(
            &zip_bytes,
            control_plane_root,
            framework_registry,
            tool_registry,
        )
    } else {
        loom_tool_registry::install::install_art_from_zip(
            &zip_bytes,
            control_plane_root,
            framework_registry,
            tool_registry,
        )
    };
    match result {
        Ok(report) => {
            let _ = broadcast_artloom_compat_arts_updated(hook_bridge);
            Ok((200, serde_json::to_string(&json!({ "report": report }))?))
        }
        Err(loom_tool_registry::install::ArtInstallError::FrameworkNotReady {
            art_id,
            framework,
            reason,
        }) => structured_error(
            409,
            json!({
                "code": "framework_not_ready",
                "message": format!("art `{art_id}` 需要框架 `{framework}`（未{reason}），请先安装该框架"),
                "framework": framework,
            }),
        ),
        Err(loom_tool_registry::install::ArtInstallError::InvalidArtId(id)) => {
            invalid_request(format!("invalid art id `{id}`"))
        }
        Err(error) => structured_error(
            400,
            json!({ "code": "art_install_failed", "message": error.to_string() }),
        ),
    }
}

fn rollback_art(
    art_id: &str,
    tool_registry: &ToolRegistry,
    framework_registry: &FrameworkRegistry,
    control_plane_root: &Path,
    hook_bridge: &SharedHookBridgeRuntime,
) -> Result<(u16, String)> {
    match loom_tool_registry::install::rollback_art_package(
        control_plane_root,
        art_id,
        tool_registry,
        framework_registry,
    ) {
        Ok(tool) => {
            let _ = broadcast_artloom_compat_arts_updated(hook_bridge);
            Ok((200, serde_json::to_string(&json!({ "tool": tool }))?))
        }
        Err(error) => structured_error(
            409,
            json!({ "code": "art_rollback_failed", "message": error.to_string() }),
        ),
    }
}

fn uninstall_art(
    art_id: &str,
    tool_registry: &ToolRegistry,
    control_plane_root: &Path,
    hook_bridge: &SharedHookBridgeRuntime,
) -> Result<(u16, String)> {
    match loom_tool_registry::install::uninstall_art_package(
        control_plane_root,
        art_id,
        tool_registry,
    ) {
        Ok(()) => {
            let _ = ArtSettingsStore::new(control_plane_root).delete(art_id);
            let _ = broadcast_artloom_compat_arts_updated(hook_bridge);
            Ok((
                200,
                serde_json::to_string(&json!({ "artId": art_id, "uninstalled": true }))?,
            ))
        }
        Err(error) => structured_error(
            400,
            json!({ "code": "art_uninstall_failed", "message": error.to_string() }),
        ),
    }
}

