    fn http_post(port: u16, path: &str, body: &str) -> String {
        let response = http_request(port, "POST", path, Some(body));
        assert!(
            response.starts_with("HTTP/1.1 200 OK"),
            "unexpected response: {response}"
        );
        response
            .split_once("\r\n\r\n")
            .expect("response body")
            .1
            .to_string()
    }

